import type { ComponentProps } from '@solidjs/web'
import {
  Popover as UiPopover,
  PopoverArrow as UiPopoverArrow,
  PopoverClose as UiPopoverClose,
  PopoverContent as UiPopoverContent,
  PopoverDescription as UiPopoverDescription,
  PopoverTitle as UiPopoverTitle,
  PopoverTrigger as UiPopoverTrigger,
} from '@ui-sdk/solid/popover'
import { omit } from 'solid-js'

import './popover.css'

/**
 * Popover, a 1:1 port of opencode's Popover (`@opencode/ui`, MIT):
 * `packages/ui/src/components/popover.css`, on top of ui-sdk's headless
 * Popover.
 *
 * Styling lives in `popover.css` as attribute rules (`data-side` on the
 * arrow), so the panel, its title, description, close part and arrow match
 * `data-component="popover-content"`. Behaviour (open and close, focus moving
 * in and back, dismissal, flipping and shifting, the arrow's offset, ARIA
 * wiring) comes from `@ui-sdk/solid`.
 *
 * Upstream's Content renders the header, description and body itself. ui-sdk
 * composes them as parts, so the content carries upstream's 12px body inset
 * as its own padding, and the author places `PopoverTitle`,
 * `PopoverDescription` and `PopoverClose` where they belong. A plain
 * `data-slot="popover-header"` wrapper rebuilds upstream's header row.
 *
 * Upstream's close button is an IconButton and its arrow an SVG path. Kitsaas
 * has no icon button, so render `PopoverClose` as a `Button` through `render`;
 * the arrow is the div ui-sdk sizes and places.
 */

type UiPopoverProps = ComponentProps<typeof UiPopover>

export type PopoverProps = UiPopoverProps

export function Popover(props: PopoverProps) {
  return <UiPopover {...props} />
}

type UiPopoverTriggerProps = ComponentProps<typeof UiPopoverTrigger>

export type PopoverTriggerProps = Omit<
  UiPopoverTriggerProps,
  'class' | 'render'
> & {
  class?: UiPopoverTriggerProps['class']
  render?: UiPopoverTriggerProps['render']
}

export function PopoverTrigger(props: PopoverTriggerProps) {
  const rest = omit(props, 'class', 'render')

  return <UiPopoverTrigger {...rest} class={props.class} render={props.render} />
}

type UiPopoverContentProps = ComponentProps<typeof UiPopoverContent>

export type PopoverContentProps = Omit<
  UiPopoverContentProps,
  'class' | 'render'
> & {
  class?: UiPopoverContentProps['class']
  render?: UiPopoverContentProps['render']
}

export function PopoverContent(props: PopoverContentProps) {
  const rest = omit(props, 'class', 'render')

  return <UiPopoverContent {...rest} class={props.class} render={props.render} />
}

type UiPopoverArrowProps = ComponentProps<typeof UiPopoverArrow>

export type PopoverArrowProps = Omit<UiPopoverArrowProps, 'class' | 'render'> & {
  class?: UiPopoverArrowProps['class']
  render?: UiPopoverArrowProps['render']
}

export function PopoverArrow(props: PopoverArrowProps) {
  const rest = omit(props, 'class', 'render')

  return <UiPopoverArrow {...rest} class={props.class} render={props.render} />
}

type UiPopoverTitleProps = ComponentProps<typeof UiPopoverTitle>

export type PopoverTitleProps = Omit<UiPopoverTitleProps, 'class' | 'render'> & {
  class?: UiPopoverTitleProps['class']
  render?: UiPopoverTitleProps['render']
}

export function PopoverTitle(props: PopoverTitleProps) {
  const rest = omit(props, 'class', 'render')

  return <UiPopoverTitle {...rest} class={props.class} render={props.render} />
}

type UiPopoverDescriptionProps = ComponentProps<typeof UiPopoverDescription>

export type PopoverDescriptionProps = Omit<
  UiPopoverDescriptionProps,
  'class' | 'render'
> & {
  class?: UiPopoverDescriptionProps['class']
  render?: UiPopoverDescriptionProps['render']
}

export function PopoverDescription(props: PopoverDescriptionProps) {
  const rest = omit(props, 'class', 'render')

  return (
    <UiPopoverDescription {...rest} class={props.class} render={props.render} />
  )
}

type UiPopoverCloseProps = ComponentProps<typeof UiPopoverClose>

export type PopoverCloseProps = Omit<
  UiPopoverCloseProps,
  'class' | 'render'
> & {
  class?: UiPopoverCloseProps['class']
  render?: UiPopoverCloseProps['render']
}

export function PopoverClose(props: PopoverCloseProps) {
  const rest = omit(props, 'class', 'render')

  return <UiPopoverClose {...rest} class={props.class} render={props.render} />
}

/*
 * 1:1 port of opencode's Popover (`@opencode/ui`, MIT):
 * packages/ui/src/components/popover.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so the panel, its title, description, close part and arrow match
 * `data-component="popover-content"`:
 *
 *   [data-component="popover-content"]   →  [data-slot="popover-content"]
 *   [data-slot="popover-trigger"]        →  same (ui-sdk's trigger slot)
 *   [data-slot="popover-header"]         →  same (upstream's own slot; a plain
 *                                            wrapper the author adds)
 *   [data-slot="popover-title"]          →  same
 *   [data-slot="popover-close-button"]   →  [data-slot="popover-close"]
 *   [data-slot="popover-description"]    →  same
 *   [data-slot="popover-body"]           →  no element; ui-sdk's content holds
 *                                            the body, so its 12px inset is the
 *                                            content's padding
 *   [data-slot="popover-arrow"]          →  same
 *
 * ui-sdk has no header or body wrapper. Upstream's 12px header and body insets
 * become the content's padding here, so the header keeps only its row layout
 * and the body needs no rule. Upstream's close button was an IconButton
 * (styled in icon-button.css), so only its `flex-shrink: 0` is carried over.
 *
 * Four upstream app-level tokens are mapped to the --v2-* token that is
 * nearest, noted at each use: --surface-raised-stronger-non-alpha,
 * --shadow-md, --text-strong and --text-base.
 *
 * ui-sdk sizes and places the arrow from its own box, where upstream filled an
 * SVG path. The 10px box, the rotation and the two border edges that continue
 * the panel border are Kitsaas glue; the fill is upstream's. `data-side` and
 * `data-align` are ui-sdk's placement attributes.
 *
 * ui-sdk renders the content in the browser's top layer with no positioner
 * element, so the content keeps upstream's z-index directly.
 *
 * popover.css has no [data-color-scheme="dark"] block: the --v2-* tokens flip
 * with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="popover-trigger"] {
    display: inline-flex;
  }

  [data-slot="popover-content"] {
    z-index: 50;
    box-sizing: border-box;
    min-width: 200px;
    max-width: 320px;
    padding: 12px;
    border-radius: var(--radius-md);

    /* upstream --surface-raised-stronger-non-alpha (#fff light); the floating
       layer is the nearest --v2-* token, as in menu and tooltip */
    background-color: var(--v2-background-bg-layer-01);

    border: 1px solid var(--v2-border-border-muted);
    background-clip: padding-box;

    /* upstream --shadow-md */
    box-shadow: var(--v2-elevation-floating);
  }

  [data-slot="popover-content"]:focus-within {
    outline: none;
  }

  /* upstream's header row, without its 12px inset, which the content carries */
  [data-slot="popover-header"] {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
  }

  [data-slot="popover-title"] {
    flex: 1;
    margin: 0;

    /* upstream --text-strong (#171717 light) */
    color: var(--v2-text-text-base);

    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    font-style: normal;
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-large);
    letter-spacing: var(--letter-spacing-normal);
  }

  [data-slot="popover-close"] {
    flex-shrink: 0;
  }

  [data-slot="popover-description"] {
    margin: 0;

    /* upstream --text-base (#6f6f6f light); grey-700 is the nearest token */
    color: var(--v2-text-text-muted);

    font-family: var(--font-family-sans);
    font-size: var(--font-size-small);
    font-style: normal;
    font-weight: var(--font-weight-regular);
    line-height: var(--line-height-large);
    letter-spacing: var(--letter-spacing-normal);
  }

  [data-slot="popover-arrow"] {
    position: absolute;
    width: 10px;
    height: 10px;
    background: var(--v2-background-bg-layer-01);
    border: 1px solid var(--v2-border-border-muted);
    transform: rotate(45deg);
    pointer-events: none;
  }

  /*
   * The arrow sits just outside the panel's edge it points from. Only the two
   * outer edges keep a border, so the light half blends into the panel.
   */
  [data-slot="popover-arrow"][data-side="bottom"] {
    top: -6px;
    border-width: 1px 0 0 1px;
  }

  [data-slot="popover-arrow"][data-side="top"] {
    bottom: -6px;
    border-width: 0 1px 1px 0;
  }

  [data-slot="popover-arrow"][data-side="left"] {
    right: -6px;
    border-width: 1px 1px 0 0;
  }

  [data-slot="popover-arrow"][data-side="right"] {
    left: -6px;
    border-width: 0 0 1px 1px;
  }
}
